preConditionHook:
// THE FAILED WEDGE. The reversal out of a three-push pattern triggers, and
// afterwards fails -- price closes back BEYOND the pattern's own extreme within a few
// bars -- so the pattern was never a reversal at all: it was a flag, and so
// the original channel resumes. A three-push BOTTOM whose bull reversal fails is a
// short; a three-push TOP whose bear reversal fails is a long.
//
// V05-17, T19-18 and V06-04 are one behaviour on one pattern family (a failed
// wedge, a failed reversal as a sign of trend strength, a failed
// expanding-triangle reversal becoming an expanding-triangle bull flag). The
// mechanizable test is the close back beyond the extreme inside a window;
// V05-17's undefined weak-breakout score is dropped in favour of it, and the
// low1 / low2 counting it also mentions is the leg counter's own pane.
//
// STATE, three variables per side. The reversal trigger is
// ThreePushReversalEntry's, recomputed here (rules never reference each
// other). When it fires, the age is set to 0 and the pattern extreme AS OF
// THAT BAR is latched. Every later bar ages the pending signal by one BEFORE
// the failure test reads it, so the test always refers to a bar strictly in
// the past, and the new-signal latch happens AFTER the test so a signal cannot
// fail on its own bar. An age of -1 means no signal is pending; ages simply
// run past failureWindowBars and stop mattering.
//
// The extreme is latched from the PREVIOUS bar's scan (loPx1Prev / hiPx1Prev),
// because the pattern the signal reverses is the pattern that existed on the
// signal bar's prior bar -- the same bar patDnPrev / patUpPrev refer to. All
// four mirrors are assigned at the top of the hook, before the scan overwrites
// them, which is how an EL variable's own one-bar history is reproduced.
//
// The final-flag twin of this rule is FailedFinalFlagTrendResumption; they are
// kept separate because the precondition is a different pattern, so different
// bars.
//
// Pivot scan as in ThreePushPattern, inlined; the register lists Occurrence 3+
// as unmeasured, so the third push is found by hand. MEASURED
// (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the pivot bar is AT
// OR ABOVE the swingStrength OLDER bars and STRICTLY ABOVE the swingStrength
// NEWER bars -- bars-ago indexing, so the newer bars are the smaller k and
// take el_gt / el_lt, the older el_ge / el_le; confirmation lag exactly
// swingStrength bars; candidate offsets swingStrength .. lookbackBars - 1, the
// neighbourhood reaching swingStrength bars past the window, so the deepest
// bar touched is lookbackBars - 1 + swingStrength. No early break.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
failWindow = (int)failureWindowBars;
patUpPrev = patUp;
patDnPrev = patDn;
hiPx1Prev = hiPx1;
loPx1Prev = loPx1;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
patUp = (nHiPiv == 3) && el_gt(hiPx1, hiPx2) && el_gt(hiPx2, hiPx3);
patDn = (nLoPiv == 3) && el_lt(loPx1, loPx2) && el_lt(loPx2, loPx3);
if (bullRevAge >= 0) bullRevAge = bullRevAge + 1;
if (bearRevAge >= 0) bearRevAge = bearRevAge + 1;
contShort = (bullRevAge >= 1) && (bullRevAge <= failWindow) && el_lt(close[0], bullRevLevel);
contLong = (bearRevAge >= 1) && (bearRevAge <= failWindow) && el_gt(close[0], bearRevLevel);
bullRevNow = patDnPrev && el_gt(close[0], high[1]);
bearRevNow = patUpPrev && el_lt(close[0], low[1]);
if (bullRevNow) {
    bullRevAge = 0;
    bullRevLevel = loPx1Prev;
}
if (bearRevNow) {
    bearRevAge = 0;
    bearRevLevel = hiPx1Prev;
}
